void Solver::bump_var(int var, double coeff) {
    double inc = var_inc * coeff;
    double updated = activity[var] + inc;
    activity[var] = updated;
    if (updated > 1e100) {
        const double SCALE = 1e-100;
        double* cur = activity + 1;
        double* limit = activity + vars + 1;
        while (cur != limit) {
            *cur++ *= SCALE;
        }
        var_inc *= SCALE;
    }
    if (vsids.inHeap(var)) vsids.update(var);
}
